        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastResult = history[history.length - 1];
            var moic = lastResult.results ? lastResult.results.moic || 1.0 : 1.0;
            var irr = lastResult.results ? lastResult.results.irr || 0 : 0;
            var performance = 'Below Hurdle';
            if (moic >= 2.5 && moic < 3.5) performance = 'Fund Hurdle Met';
            if (moic >= 3.5 && moic < 4.5) performance = 'Strong Performance';
            if (moic >= 4.5) performance = 'Exceptional — Top Quartile PE';
            var insights = [];
            if (moic >= 4.0) insights.push(window.mySimulation.t('insight_excellent'));
            else if (moic >= 3.0) insights.push(window.mySimulation.t('insight_good'));
            else if (moic >= 2.0) insights.push(window.mySimulation.t('insight_moderate'));
            else insights.push(window.mySimulation.t('insight_poor'));
            var peScore = lastResult.results ? (lastResult.results.peScore || 0) : 0;
            var covenantOutcome = lastResult.results ? (lastResult.results.covenantOutcome || 'ok') : 'ok';
            return { moic: moic, irr: irr, score: peScore, covenantOutcome: covenantOutcome, performance: performance, insights: insights };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.coverage < 2.0) return window.mySimulation.t('hint_coverage_danger');
            if (results.leverage > 5.0) return window.mySimulation.t('hint_leverage_high');
            if (results.moic > 3.5) return window.mySimulation.t('hint_strong_return');
